internal object LauncherTranslationChunk3 {
    val entries = mapOf(
        "Detected a previous Jester direct-patch installation" to arrayOf("Natukoy ang isang naunang Jester direct-patch na pag-install", "\uC774\uC804 Jester \uC9C1\uC811 \uD328\uCE58 \uC124\uCE58\uAC00 \uAC10\uC9C0\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u4EE5\u524D\u306EJester\u76F4\u63A5\u30D1\u30C3\u30C1\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u304C\u691C\u51FA\u3055\u308C\u307E\u3057\u305F", "\u68C0\u6D4B\u5230\u5148\u524D\u7684 Jester \u76F4\u63A5\u4FEE\u8865\u5B89\u88C5", "Se detect\u00F3 una instalaci\u00F3n anterior de parche directo de Jester", "Ph\u00E1t hi\u1EC7n c\u00E0i \u0111\u1EB7t v\u00E1 tr\u1EF1c ti\u1EBFp Jester tr\u01B0\u1EDBc \u0111\u00F3", "Terdeteksi instalasi patch langsung Jester sebelumnya", "Instalacao direta anterior do patch Jester detectada", "تم اكتشاف تثبيت تصحيح مباشر سابق لـ Jester"),
        "Device security check failed" to arrayOf("Nabigo ang device security check", "\uC7A5\uCE58 \uBCF4\uC548 \uAC80\uC0AC \uC2E4\uD328", "\u30C7\u30D0\u30A4\u30B9\u306E\u30BB\u30AD\u30E5\u30EA\u30C6\u30A3\u30C1\u30A7\u30C3\u30AF\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u8BBE\u5907\u5B89\u5168\u68C0\u67E5\u5931\u8D25", "Fall\u00F3 la verificaci\u00F3n de seguridad del dispositivo", "Ki\u1EC3m tra b\u1EA3o m\u1EADt thi\u1EBFt b\u1ECB th\u1EA5t b\u1EA1i", "Pemeriksaan keamanan perangkat gagal", "Verifica\u00E7\u00E3o de seguran\u00E7a do dispositivo falhou", "فشل فحص أمان الجهاز"),
        "Digital key check failed before a new protected action" to arrayOf("Nabigo ang digital key check bago ang bagong protektadong aksyon", "\uC0C8\uB85C\uC6B4 \uBCF4\uD638\uB41C \uC791\uC5C5 \uC804\uC5D0 \uB514\uC9C0\uD138 \uD0A4 \uAC80\uC0AC \uC2E4\uD328", "\u65B0\u3057\u3044\u4FDD\u8B77\u30A2\u30AF\u30B7\u30E7\u30F3\u306E\u524D\u306B\u30C7\u30B8\u30BF\u30EB\u30AD\u30FC\u306E\u30C1\u30A7\u30C3\u30AF\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u5728\u65B0\u7684\u53D7\u4FDD\u62A4\u64CD\u4F5C\u4E4B\u524D\u6570\u5B57\u5BC6\u94A5\u68C0\u67E5\u5931\u8D25", "Fall\u00F3 la verificaci\u00F3n de la clave digital antes de una nueva acci\u00F3n protegida", "Ki\u1EC3m tra kh\u00F3a s\u1ED1 th\u1EA5t b\u1EA1i tr\u01B0\u1EDBc m\u1ED9t h\u00E0nh \u0111\u1ED9ng \u0111\u01B0\u1EE3c b\u1EA3o v\u1EC7 m\u1EDBi", "Pemeriksaan kunci digital gagal sebelum aksi terlindungi baru", "Verifica\u00E7\u00E3o da chave digital falhou antes de uma nova a\u00E7\u00E3o protegida", "فشل فحص المفتاح الرقمي قبل اتخاذ إجراء محمي جديد"),
        "Digital key recovery check failed" to arrayOf("Nabigo ang digital key recovery check", "\uB514\uC9C0\uD138 \uD0A4 \uBCF5\uAD6C \uAC80\uC0AC \uC2E4\uD328", "\u30C7\u30B8\u30BF\u30EB\u30AD\u30FC\u306E\u56DE\u5FA9\u30C1\u30A7\u30C3\u30AF\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u6570\u5B57\u5BC6\u94A5\u6062\u590D\u68C0\u67E5\u5931\u8D25", "Fall\u00F3 la verificaci\u00F3n de recuperaci\u00F3n de la clave digital", "Ki\u1EC3m tra ph\u1EE5c h\u1ED3i kh\u00F3a s\u1ED1 th\u1EA5t b\u1EA1i", "Pemeriksaan pemulihan kunci digital gagal", "Verifica\u00E7\u00E3o de recupera\u00E7\u00E3o da chave digital falhou", "فشل التحقق من استرداد المفتاح الرقمي"),
        "Digital key redemption failed" to arrayOf("Nabigo ang digital key redemption", "\uB514\uC9C0\uD138 \uD0A4 \uC0AC\uC6A9 \uC2E4\uD328", "\u30C7\u30B8\u30BF\u30EB\u30AD\u30FC\u306E\u4EA4\u63DB\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u6570\u5B57\u5BC6\u94A5\u5151\u6362\u5931\u8D25", "Fall\u00F3 el canje de la clave digital", "\u0110\u1ED5i kh\u00F3a s\u1ED1 th\u1EA5t b\u1EA1i", "Penukaran kunci digital gagal", "Resgate da chave digital falhou", "فشل استرداد المفتاح الرقمي"),
        "Discover what is included, confirm compatibility, and choose how to add it." to arrayOf("Tuklasin kung ano ang kasama, kumpirmahin ang pagiging compatible, at piliin kung paano idagdag ito.", "\uD3EC\uD568\uB41C \uB0B4\uC6A9\uC744 \uD655\uC778\uD558\uACE0, \uD638\uD658\uC131\uC744 \uD655\uC778\uD558\uBA70, \uCD94\uAC00 \uBC29\uBC95\uC744 \uC120\uD0DD\uD558\uC2ED\uC2DC\uC624.", "\u542B\u307E\u308C\u3066\u3044\u308B\u3082\u306E\u3092\u78BA\u8A8D\u3057\u3001\u4E92\u63DB\u6027\u3092\u78BA\u8A8D\u3057\u3066\u3001\u8FFD\u52A0\u65B9\u6CD5\u3092\u9078\u629E\u3057\u307E\u3059\u3002", "\u53D1\u73B0\u5305\u542B\u7684\u5185\u5BB9\uFF0C\u786E\u8BA4\u517C\u5BB9\u6027\uFF0C\u5E76\u9009\u62E9\u5982\u4F55\u6DFB\u52A0\u3002", "Descubre lo que est\u00E1 incluido, confirma la compatibilidad y elige c\u00F3mo agregarlo.", "Kh\u00E1m ph\u00E1 nh\u1EEFng g\u00EC \u0111\u01B0\u1EE3c bao g\u1ED3m, x\u00E1c nh\u1EADn kh\u1EA3 n\u0103ng t\u01B0\u01A1ng th\u00EDch, v\u00E0 ch\u1ECDn c\u00E1ch th\u00EAm n\u00F3.", "Temukan apa saja yang termasuk, konfirmasi kompatibilitas, dan pilih cara menambahkannya.", "Descubra o que est\u00E1 inclu\u00EDdo, confirme a compatibilidade e escolha como adicionar.", "اكتشف ما تم تضمينه، وتأكد من التوافق، واختر كيفية إضافته."),
        "Download authorization expired" to arrayOf("Expired ang authorization sa pag-download", "\uB2E4\uC6B4\uB85C\uB4DC \uAD8C\uD55C \uB9CC\uB8CC", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u8A8D\u8A3C\u306E\u6709\u52B9\u671F\u9650\u304C\u5207\u308C\u307E\u3057\u305F", "\u4E0B\u8F7D\u6388\u6743\u5DF2\u8FC7\u671F", "La autorizaci\u00F3n de descarga ha expirado", "\u1EE6y quy\u1EC1n t\u1EA3i xu\u1ED1ng \u0111\u00E3 h\u1EBFt h\u1EA1n", "Otorisasi unduhan telah kadaluarsa", "Autoriza\u00E7\u00E3o de download expirou", "انتهت صلاحية ترخيص التنزيل"),
        "Download complete" to arrayOf("Kumpleto na ang pag-download", "\uB2E4\uC6B4\uB85C\uB4DC \uC644\uB8CC", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u5B8C\u4E86", "\u4E0B\u8F7D\u5B8C\u6210", "Descarga completa", "T\u1EA3i xu\u1ED1ng ho\u00E0n t\u1EA5t", "Unduhan selesai", "Download completo", "اكتمل التنزيل"),
