        "Downloading add-on" to arrayOf("I-dodownload ang add-on", "\uC560\uB4DC\uC628 \uB2E4\uC6B4\uB85C\uB4DC \uC911", "\u30A2\u30C9\u30AA\u30F3\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D", "\u6B63\u5728\u4E0B\u8F7D\u9644\u52A0\u7EC4\u4EF6", "Descargando complemento", "\u0110ang t\u1EA3i ti\u1EC7n \u00EDch b\u1ED5 sung", "Mengunduh add-on", "Baixando complemento", "جارٍ تنزيل الوظيفة الإضافية"),
