        "Downloading original game" to arrayOf("I-dodownload ang orihinal na laro", "\uC6D0\uBCF8 \uAC8C\uC784 \uB2E4\uC6B4\uB85C\uB4DC \uC911", "\u30AA\u30EA\u30B8\u30CA\u30EB\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D", "\u6B63\u5728\u4E0B\u8F7D\u539F\u59CB\u6E38\u620F", "Descargando juego original", "\u0110ang t\u1EA3i tr\u00F2 ch\u01A1i g\u1ED1c", "Mengunduh game asli", "Baixando jogo original", "تحميل اللعبة الاصلية"),
        "Downloading secure package" to arrayOf("I-dodownload ang secure na pakete", "\uBCF4\uC548 \uD328\uD0A4\uC9C0 \uB2E4\uC6B4\uB85C\uB4DC \uC911", "\u30BB\u30AD\u30E5\u30A2\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D", "\u6B63\u5728\u4E0B\u8F7D\u5B89\u5168\u5305", "Descargando paquete seguro", "\u0110ang t\u1EA3i g\u00F3i b\u1EA3o m\u1EADt", "Mengunduh paket aman", "Baixando pacote seguro", "تنزيل الحزمة الآمنة"),
        "Downloading the latest add-on for {0}." to arrayOf("I-dodownload ang pinakabagong add-on para sa {0}", "{0}\uC6A9 \uCD5C\uC2E0 \uC560\uB4DC\uC628 \uB2E4\uC6B4\uB85C\uB4DC \uC911", "{0} \u306E\u6700\u65B0\u30A2\u30C9\u30AA\u30F3\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D", "\u6B63\u5728\u4E0B\u8F7D {0} \u7684\u6700\u65B0\u9644\u52A0\u7EC4\u4EF6", "Descargando el \u00FAltimo complemento para {0}.", "\u0110ang t\u1EA3i ti\u1EC7n \u00EDch b\u1ED5 sung m\u1EDBi nh\u1EA5t cho {0}", "Mengunduh add-on terbaru untuk {0}.", "Baixando o complemento mais recente para {0}.", "تنزيل أحدث وظيفة إضافية لـ {0}."),
        "Downloading update" to arrayOf("I-dodownload ang update", "\uC5C5\uB370\uC774\uD2B8 \uB2E4\uC6B4\uB85C\uB4DC \uC911", "\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D", "\u6B63\u5728\u4E0B\u8F7D\u66F4\u65B0", "Descargando actualizaci\u00F3n", "\u0110ang t\u1EA3i c\u1EADp nh\u1EADt", "Mengunduh pembaruan", "Baixando atualiza\u00E7\u00E3o", "جارٍ تنزيل التحديث"),
        "Embedded local test installation failed; normal launcher startup will continue." to arrayOf("Nabigong i-install ang embedded local test; magpapatuloy ang normal na pagsisimula ng launcher", "\uB0B4\uC7A5 \uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uC124\uCE58 \uC2E4\uD328; \uC815\uC0C1 \uB7F0\uCC98 \uC2DC\uC791\uC744 \uACC4\uC18D\uD569\uB2C8\uB2E4.", "\u57CB\u3081\u8FBC\u307F\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306B\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u901A\u5E38\u306E\u30E9\u30F3\u30C1\u30E3\u30FC\u8D77\u52D5\u3092\u7D9A\u884C\u3057\u307E\u3059\u3002", "\u5D4C\u5165\u7684\u672C\u5730\u6D4B\u8BD5\u5B89\u88C5\u5931\u8D25\uFF1B\u5C06\u7EE7\u7EED\u6B63\u5E38\u542F\u52A8\u5668\u542F\u52A8\u3002", "La instalaci\u00F3n de prueba local integrada fall\u00F3; se continuar\u00E1 con el inicio normal del lanzador.", "C\u00E0i \u0111\u1EB7t th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 nh\u00FAng th\u1EA5t b\u1EA1i; tr\u00ECnh kh\u1EDFi ch\u1EA1y th\u00F4ng th\u01B0\u1EDDng s\u1EBD ti\u1EBFp t\u1EE5c kh\u1EDFi \u0111\u1ED9ng.", "Instalasi uji lokal tersemat gagal; peluncur normal akan dilanjutkan.", "Falha na instala\u00E7\u00E3o de teste local embutida; o in\u00EDcio normal do launcher continuar\u00E1.", "فشل تثبيت الاختبار المحلي المضمن؛ سيستمر بدء التشغيل العادي للمشغل."),
        "Embedded module installation failed; normal launcher startup will continue." to arrayOf("Nabigong i-install ang embedded module; magpapatuloy ang normal na pagsisimula ng launcher", "\uB0B4\uC7A5 \uBAA8\uB4C8 \uC124\uCE58 \uC2E4\uD328; \uC815\uC0C1 \uB7F0\uCC98 \uC2DC\uC791\uC744 \uACC4\uC18D\uD569\uB2C8\uB2E4.", "\u57CB\u3081\u8FBC\u307F\u30E2\u30B8\u30E5\u30FC\u30EB\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306B\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u901A\u5E38\u306E\u30E9\u30F3\u30C1\u30E3\u30FC\u8D77\u52D5\u3092\u7D9A\u884C\u3057\u307E\u3059\u3002", "\u5D4C\u5165\u7684\u6A21\u5757\u5B89\u88C5\u5931\u8D25\uFF1B\u5C06\u7EE7\u7EED\u6B63\u5E38\u542F\u52A8\u5668\u542F\u52A8\u3002", "La instalaci\u00F3n del m\u00F3dulo integrado fall\u00F3; se continuar\u00E1 con el inicio normal del lanzador.", "C\u00E0i \u0111\u1EB7t m\u00F4-\u0111un nh\u00FAng th\u1EA5t b\u1EA1i; tr\u00ECnh kh\u1EDFi ch\u1EA1y th\u00F4ng th\u01B0\u1EDDng s\u1EBD ti\u1EBFp t\u1EE5c kh\u1EDFi \u0111\u1ED9ng.", "Instalasi modul tersemat gagal; peluncur normal akan dilanjutkan.", "Falha na instala\u00E7\u00E3o do m\u00F3dulo embutido; o in\u00EDcio normal do launcher continuar\u00E1.", "فشل تثبيت الوحدة المضمنة؛ سيستمر بدء التشغيل العادي للمشغل."),
        "External app test storage is unavailable" to arrayOf("Hindi magagamit ang external app test storage", "\uC678\uBD80 \uC571 \uD14C\uC2A4\uD2B8 \uC800\uC7A5\uC18C\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC74C", "\u5916\u90E8\u30A2\u30D7\u30EA\u306E\u30C6\u30B9\u30C8\u30B9\u30C8\u30EC\u30FC\u30B8\u304C\u5229\u7528\u3067\u304D\u307E\u305B\u3093", "\u5916\u90E8\u5E94\u7528\u6D4B\u8BD5\u5B58\u50A8\u4E0D\u53EF\u7528", "El almacenamiento de prueba de la aplicaci\u00F3n externa no est\u00E1 disponible", "B\u1ED9 nh\u1EDB th\u1EED nghi\u1EC7m \u1EE9ng d\u1EE5ng b\u00EAn ngo\u00E0i kh\u00F4ng kh\u1EA3 d\u1EE5ng", "Penyimpanan uji aplikasi eksternal tidak tersedia", "Armazenamento de teste de aplicativo externo indispon\u00EDvel", "مساحة تخزين اختبار التطبيق الخارجي غير متاحة"),
        "Finishing the current file operation without damaging the resumable download." to arrayOf("Tinatapos ang kasalukuyang operasyon sa file nang hindi nasisira ang resumable na pag-download", "\uB2E4\uC2DC \uC2DC\uC791 \uAC00\uB2A5\uD55C \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC190\uC0C1\uC2DC\uD0A4\uC9C0 \uC54A\uACE0 \uD604\uC7AC \uD30C\uC77C \uC791\uC5C5 \uC644\uB8CC \uC911", "\u518D\u958B\u53EF\u80FD\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u640D\u306A\u3046\u3053\u3068\u306A\u304F\u3001\u73FE\u5728\u306E\u30D5\u30A1\u30A4\u30EB\u64CD\u4F5C\u3092\u7D42\u4E86\u3057\u3066\u3044\u307E\u3059\u3002", "\u5B8C\u6210\u5F53\u524D\u6587\u4EF6\u64CD\u4F5C\u800C\u4E0D\u4F1A\u7834\u574F\u53EF\u6062\u590D\u4E0B\u8F7D\u3002", "Finalizando la operaci\u00F3n de archivo actual sin da\u00F1ar la descarga reanudable.", "Ho\u00E0n t\u1EA5t thao t\u00E1c t\u1EC7p hi\u1EC7n t\u1EA1i m\u00E0 kh\u00F4ng l\u00E0m h\u1ECFng qu\u00E1 tr\u00ECnh t\u1EA3i xu\u1ED1ng c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c.", "Menyelesaikan operasi file saat ini tanpa merusak unduhan yang dapat dilanjutkan.", "Finalizando a opera\u00E7\u00E3o de arquivo atual sem prejudicar o download que pode ser retomado.", "إنهاء عملية الملف الحالي دون الإضرار بالتنزيل القابل للاستئناف."),
        "Finishing update" to arrayOf("Tinatapos ang update", "\uC5C5\uB370\uC774\uD2B8 \uC644\uB8CC \uC911", "\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u3092\u7D42\u4E86\u4E2D", "\u5B8C\u6210\u66F4\u65B0", "Finalizando actualizaci\u00F3n", "Ho\u00E0n t\u1EA5t c\u1EADp nh\u1EADt", "Menyelesaikan pembaruan", "Finalizando atualiza\u00E7\u00E3o", "الانتهاء من التحديث"),
        "Finishing {0} cleanup" to arrayOf("Tinatapos ang paglilinis ng {0}", "{0} \uC815\uB9AC \uC644\uB8CC \uC911", "{0} \u306E\u30AF\u30EA\u30FC\u30F3\u30A2\u30C3\u30D7\u3092\u7D42\u4E86\u4E2D", "\u5B8C\u6210 {0} \u6E05\u7406", "Finalizando limpieza de {0}", "Ho\u00E0n t\u1EA5t d\u1ECDn d\u1EB9p {0}", "Menyelesaikan pembersihan {0}", "Finalizando a limpeza de {0}", "الانتهاء من تنظيف {0}."),
        "Finishing {0} uninstall" to arrayOf("Tinatapos ang pag-uninstall ng {0}", "{0} \uC81C\uAC70 \uC644\uB8CC \uC911", "{0} \u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u7D42\u4E86\u4E2D", "\u5B8C\u6210 {0} \u5378\u8F7D", "Finalizando desinstalaci\u00F3n de {0}", "Ho\u00E0n t\u1EA5t g\u1EE1 c\u00E0i \u0111\u1EB7t {0}", "Menyelesaikan pencopotan {0}", "Finalizando a desinstala\u00E7\u00E3o de {0}", "جارٍ الانتهاء من إلغاء تثبيت {0}."),
        "Free some device storage, then try again. Any safely saved download progress can be reused." to arrayOf("Magbakante ng ilang storage ng device, pagkatapos ay subukang muli. Maaaring magamit muli ang anumang ligtas na na-save na progreso ng pag-download", "\uC7A5\uCE58 \uC800\uC7A5 \uACF5\uAC04\uC744 \uD655\uBCF4\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694. \uC548\uC804\uD558\uAC8C \uC800\uC7A5\uB41C \uB2E4\uC6B4\uB85C\uB4DC \uC9C4\uD589 \uC0C1\uD669\uC740 \uC7AC\uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u30C7\u30D0\u30A4\u30B9\u306E\u30B9\u30C8\u30EC\u30FC\u30B8\u3092\u5C11\u3057\u89E3\u653E\u3057\u3066\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u5B89\u5168\u306B\u4FDD\u5B58\u3055\u308C\u305F\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u9032\u884C\u72B6\u6CC1\u306F\u518D\u5229\u7528\u53EF\u80FD\u3067\u3059\u3002", "\u91CA\u653E\u4E00\u4E9B\u8BBE\u5907\u5B58\u50A8\uFF0C\u7136\u540E\u91CD\u8BD5\u3002\u4EFB\u4F55\u5B89\u5168\u4FDD\u5B58\u7684\u4E0B\u8F7D\u8FDB\u5EA6\u90FD\u53EF\u4EE5\u91CD\u590D\u4F7F\u7528\u3002", "Libera algo de espacio de almacenamiento del dispositivo y luego intenta nuevamente. Cualquier progreso de descarga guardado de forma segura puede reutilizarse.", "Gi\u1EA3i ph\u00F3ng m\u1ED9t s\u1ED1 dung l\u01B0\u1EE3ng thi\u1EBFt b\u1ECB, sau \u0111\u00F3 th\u1EED l\u1EA1i. B\u1EA5t k\u1EF3 ti\u1EBFn tr\u00ECnh t\u1EA3i xu\u1ED1ng n\u00E0o \u0111\u00E3 \u0111\u01B0\u1EE3c l\u01B0u an to\u00E0n \u0111\u1EC1u c\u00F3 th\u1EC3 s\u1EED d\u1EE5ng l\u1EA1i.", "Bebaskan beberapa penyimpanan perangkat, lalu coba lagi. Setiap progres unduhan yang tersimpan dengan aman dapat digunakan kembali.", "Libere algum espa\u00E7o no dispositivo e tente novamente. Qualquer progresso de download salvo com seguran\u00E7a pode ser reutilizado.", "قم بتحرير بعض مساحة تخزين الجهاز، ثم حاول مرة أخرى. يمكن إعادة استخدام أي تقدم تم حفظه في التنزيل بشكل آمن."),
        "Game" to arrayOf("Laro", "\uAC8C\uC784", "\u30B2\u30FC\u30E0", "\u6E38\u620F", "Juego", "Tr\u00F2 ch\u01A1i", "Game", "Jogo", "لعبة"),
        "Game data cleared" to arrayOf("Nakalinis ang data ng laro", "\uAC8C\uC784 \uB370\uC774\uD130 \uC0AD\uC81C\uB428", "\u30B2\u30FC\u30E0\u30C7\u30FC\u30BF\u304C\u30AF\u30EA\u30A2\u3055\u308C\u307E\u3057\u305F", "\u6E38\u620F\u6570\u636E\u5DF2\u6E05\u9664", "Datos del juego borrados", "D\u1EEF li\u1EC7u tr\u00F2 ch\u01A1i \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00F3a", "Data permainan dibersihkan", "Dados do jogo apagados", "تم مسح بيانات اللعبة"),
        "Game download or install failed" to arrayOf("Nabigong i-download o i-install ang laro", "\uAC8C\uC784 \uB2E4\uC6B4\uB85C\uB4DC \uB610\uB294 \uC124\uCE58 \uC2E4\uD328", "\u30B2\u30FC\u30E0\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u307E\u305F\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u6E38\u620F\u4E0B\u8F7D\u6216\u5B89\u88C5\u5931\u8D25", "Fall\u00F3 la descarga o instalaci\u00F3n del juego", "T\u1EA3i xu\u1ED1ng ho\u1EB7c c\u00E0i \u0111\u1EB7t tr\u00F2 ch\u01A1i th\u1EA5t b\u1EA1i", "Unduhan atau pemasangan permainan gagal", "Falha no download ou instala\u00E7\u00E3o do jogo", "فشل تنزيل اللعبة أو تثبيتها"),
        "Game support {0} failed" to arrayOf("Nabigong suportahan ng laro ang {0}", "\uAC8C\uC784 \uC9C0\uC6D0 {0} \uC2E4\uD328", "\u30B2\u30FC\u30E0\u30B5\u30DD\u30FC\u30C8 {0} \u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u6E38\u620F\u652F\u6301 {0} \u5931\u8D25", "Fall\u00F3 el soporte del juego {0}", "H\u1ED7 tr\u1EE3 tr\u00F2 ch\u01A1i {0} th\u1EA5t b\u1EA1i", "Dukungan permainan {0} gagal", "Falha no suporte ao jogo {0}", "فشل دعم اللعبة {0}."),
        "Getting everything ready." to arrayOf("Inihahanda ang lahat.", "\uBAA8\uB4E0 \uC900\uBE44 \uC911.", "\u6E96\u5099\u3092\u6574\u3048\u3066\u3044\u307E\u3059\u3002", "\u6B63\u5728\u51C6\u5907\u6240\u6709\u5185\u5BB9\u3002", "Preparando todo.", "\u0110ang chu\u1EA9n b\u1ECB m\u1ECDi th\u1EE9.", "Menyiapkan semuanya.", "Preparando tudo.", "تجهيز كل شيء."),
        "Getting things ready" to arrayOf("Inihahanda ang mga bagay", "\uC900\uBE44 \uC911", "\u6E96\u5099\u3092\u9032\u3081\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u4E8B\u9879", "Preparando las cosas", "\u0110ang chu\u1EA9n b\u1ECB c\u00E1c th\u1EE9", "Menyiapkan barang-barang", "Preparando as coisas", "تحضير الأشياء"),
        "Getting {0} ready for Jester Mods." to arrayOf("Inihahanda ang {0} para sa Jester Mods.", "{0}\uB97C Jester Mods\uC6A9\uC73C\uB85C \uC900\uBE44 \uC911.", "{0} \u3092 Jester Mods \u7528\u306B\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u3002", "\u6B63\u5728\u4E3A Jester Mods \u51C6\u5907 {0}\u3002", "Preparando {0} para Jester Mods.", "\u0110ang chu\u1EA9n b\u1ECB {0} cho Jester Mods.", "Menyiapkan {0} untuk Jester Mods.", "Preparando {0} para o Jester Mods.", "جارٍ تجهيز {0} لتعديلات Jester."),
        "If Android's confirmation is still visible, close it there. The verified download remains saved." to arrayOf("Kung nakikita pa rin ang kumpirmasyon ng Android, isara ito roon. Mananatiling naka-save ang napatunayang download.", "Android \uD655\uC778 \uCC3D\uC774 \uC5EC\uC804\uD788 \uBCF4\uC774\uBA74, \uADF8\uACF3\uC5D0\uC11C \uB2EB\uC73C\uC138\uC694. \uAC80\uC99D\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB294 \uC800\uC7A5\uB429\uB2C8\uB2E4.", "Android \u306E\u78BA\u8A8D\u753B\u9762\u304C\u307E\u3060\u8868\u793A\u3055\u308C\u3066\u3044\u308B\u5834\u5408\u306F\u3001\u305D\u3053\u3067\u9589\u3058\u3066\u304F\u3060\u3055\u3044\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u4FDD\u5B58\u3055\u308C\u305F\u307E\u307E\u3067\u3059\u3002", "\u5982\u679C Android \u7684\u786E\u8BA4\u4ECD\u7136\u663E\u793A\uFF0C\u8BF7\u5728\u90A3\u91CC\u5173\u95ED\u3002\u5DF2\u9A8C\u8BC1\u7684\u4E0B\u8F7D\u4ECD\u7136\u4FDD\u5B58\u3002", "Si la confirmaci\u00F3n de Android a\u00FAn est\u00E1 visible, ci\u00E9rrala all\u00ED. La descarga verificada permanece guardada.", "N\u1EBFu x\u00E1c nh\u1EADn c\u1EE7a Android v\u1EABn c\u00F2n hi\u1EC3n th\u1ECB, h\u00E3y \u0111\u00F3ng n\u00F3 \u1EDF \u0111\u00F3. T\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c th\u1EF1c v\u1EABn \u0111\u01B0\u1EE3c l\u01B0u.", "Jika konfirmasi Android masih terlihat, tutup di sana. Unduhan yang terverifikasi tetap tersimpan.", "Se a confirma\u00E7\u00E3o do Android ainda estiver vis\u00EDvel, feche-a l\u00E1. O download verificado permanece salvo.", "إذا كان تأكيد Android لا يزال مرئيًا، فأغلقه هناك. يظل التنزيل الذي تم التحقق منه محفوظًا."),
        "If Android's installer is still visible, close it there. The verified update remains saved." to arrayOf("Kung nakikita pa rin ang installer ng Android, isara ito roon. Mananatiling naka-save ang napatunayang update.", "Android \uC124\uCE58 \uAD00\uB9AC\uC790\uAC00 \uC5EC\uC804\uD788 \uBCF4\uC774\uBA74, \uADF8\uACF3\uC5D0\uC11C \uB2EB\uC73C\uC138\uC694. \uAC80\uC99D\uB41C \uC5C5\uB370\uC774\uD2B8\uB294 \uC800\uC7A5\uB429\uB2C8\uB2E4.", "Android \u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u307E\u3060\u8868\u793A\u3055\u308C\u3066\u3044\u308B\u5834\u5408\u306F\u3001\u305D\u3053\u3067\u9589\u3058\u3066\u304F\u3060\u3055\u3044\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u306F\u4FDD\u5B58\u3055\u308C\u305F\u307E\u307E\u3067\u3059\u3002", "\u5982\u679C Android \u7684\u5B89\u88C5\u7A0B\u5E8F\u4ECD\u7136\u663E\u793A\uFF0C\u8BF7\u5728\u90A3\u91CC\u5173\u95ED\u3002\u5DF2\u9A8C\u8BC1\u7684\u66F4\u65B0\u4ECD\u7136\u4FDD\u5B58\u3002", "Si el instalador de Android a\u00FAn est\u00E1 visible, ci\u00E9rralo all\u00ED. La actualizaci\u00F3n verificada permanece guardada.", "N\u1EBFu tr\u00ECnh c\u00E0i \u0111\u1EB7t c\u1EE7a Android v\u1EABn c\u00F2n hi\u1EC3n th\u1ECB, h\u00E3y \u0111\u00F3ng n\u00F3 \u1EDF \u0111\u00F3. B\u1EA3n c\u1EADp nh\u1EADt \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c th\u1EF1c v\u1EABn \u0111\u01B0\u1EE3c l\u01B0u.", "Jika penginstal Android masih terlihat, tutup di sana. Pembaruan yang terverifikasi tetap tersimpan.", "Se o instalador do Android ainda estiver vis\u00EDvel, feche-o l\u00E1. A atualiza\u00E7\u00E3o verificada permanece salva.", "إذا كان برنامج تثبيت Android لا يزال مرئيًا، فأغلقه هناك. يظل التحديث الذي تم التحقق منه محفوظًا."),
        "Inspecting local download cache" to arrayOf("Sinusuri ang lokal na download cache", "\uB85C\uCEEC \uB2E4\uC6B4\uB85C\uB4DC \uCE90\uC2DC \uAC80\uC0AC \uC911", "\u30ED\u30FC\u30AB\u30EB\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u30AD\u30E3\u30C3\u30B7\u30E5\u3092\u78BA\u8A8D\u3057\u3066\u3044\u307E\u3059", "\u68C0\u67E5\u672C\u5730\u4E0B\u8F7D\u7F13\u5B58", "Inspeccionando cach\u00E9 de descargas local", "Ki\u1EC3m tra b\u1ED9 nh\u1EDB \u0111\u1EC7m t\u1EA3i xu\u1ED1ng c\u1EE5c b\u1ED9", "Memeriksa cache unduhan lokal", "Inspecionando o cache de download local", "فحص ذاكرة التخزين المؤقت للتنزيل المحلي"),
        "Install or enable a browser, then try again." to arrayOf("Mag-install o paganahin ang browser, pagkatapos subukang muli.", "\uBE0C\uB77C\uC6B0\uC800\uB97C \uC124\uCE58\uD558\uAC70\uB098 \uD65C\uC131\uD654\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30D6\u30E9\u30A6\u30B6\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u307E\u305F\u306F\u6709\u52B9\u306B\u3057\u3066\u304B\u3089\u3001\u3082\u3046\u4E00\u5EA6\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002", "\u5B89\u88C5\u6216\u542F\u7528\u6D4F\u89C8\u5668\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Instala o habilita un navegador, luego intenta de nuevo.", "C\u00E0i \u0111\u1EB7t ho\u1EB7c b\u1EADt tr\u00ECnh duy\u1EC7t, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Pasang atau aktifkan browser, lalu coba lagi.", "Instale ou habilite um navegador, ent\u00E3o tente novamente.", "قم بتثبيت المتصفح أو تمكينه، ثم حاول مرة أخرى."),
        "Install or update the original game there, then return to Jester Mods." to arrayOf("Mag-install o i-update ang orihinal na laro roon, pagkatapos bumalik sa Jester Mods.", "\uC6D0\uBCF8 \uAC8C\uC784\uC744 \uC124\uCE58\uD558\uAC70\uB098 \uC5C5\uB370\uC774\uD2B8\uD55C \uD6C4 Jester Mods\uB85C \uB3CC\uC544\uAC00\uC138\uC694.", "\u305D\u3053\u3067\u5143\u306E\u30B2\u30FC\u30E0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u307E\u305F\u306F\u66F4\u65B0\u3057\u3066\u304B\u3089\u3001Jester Mods \u306B\u623B\u3063\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728\u90A3\u5B89\u88C5\u6216\u66F4\u65B0\u539F\u59CB\u6E38\u620F\uFF0C\u7136\u540E\u8FD4\u56DE Jester Mods\u3002", "Instala o actualiza el juego original all\u00ED, luego vuelve a Jester Mods.", "C\u00E0i \u0111\u1EB7t ho\u1EB7c c\u1EADp nh\u1EADt tr\u00F2 ch\u01A1i g\u1ED1c \u1EDF \u0111\u00F3, sau \u0111\u00F3 quay l\u1EA1i Jester Mods.", "Pasang atau perbarui game asli di sana, lalu kembali ke Jester Mods.", "Instale ou atualize o jogo original l\u00E1, ent\u00E3o volte para o Jester Mods.", "قم بتثبيت اللعبة الأصلية أو تحديثها هناك، ثم ارجع إلى Jester Mods."),
        "Install the game-branded shell" to arrayOf("I-install ang game-branded shell", "\uAC8C\uC784 \uBE0C\uB79C\uB4DC \uC178 \uC124\uCE58", "\u30B2\u30FC\u30E0\u30D6\u30E9\u30F3\u30C9\u306E\u30B7\u30A7\u30EB\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u304F\u3060\u3055\u3044", "\u5B89\u88C5\u6E38\u620F\u54C1\u724C\u5916\u58F3", "Instala la interfaz con la marca del juego", "C\u00E0i \u0111\u1EB7t giao di\u1EC7n tr\u00F2 ch\u01A1i c\u00F3 th\u01B0\u01A1ng hi\u1EC7u", "Pasang shell bermerk game", "Instale o shell do jogo com a marca", "قم بتثبيت الغلاف الذي يحمل العلامة التجارية للعبة"),
        "Install the latest Jester Mods Launcher update, then retry." to arrayOf("I-install ang pinakabagong update ng Jester Mods Launcher, pagkatapos subukang muli.", "\uCD5C\uC2E0 Jester Mods \uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8\uB97C \uC124\uCE58\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u6700\u65B0\u306E Jester Mods \u30E9\u30F3\u30C1\u30E3\u30FC\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u304B\u3089\u3001\u3082\u3046\u4E00\u5EA6\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002", "\u5B89\u88C5\u6700\u65B0\u7684 Jester Mods \u542F\u52A8\u5668\u66F4\u65B0\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Instala la \u00FAltima actualizaci\u00F3n del Lanzador de Jester Mods, luego reintenta.", "C\u00E0i \u0111\u1EB7t b\u1EA3n c\u1EADp nh\u1EADt Jester Mods Launcher m\u1EDBi nh\u1EA5t, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Pasang pembaruan terbaru Jester Mods Launcher, lalu coba lagi.", "Instale a atualiza\u00E7\u00E3o mais recente do Jester Mods Launcher, ent\u00E3o tente novamente.", "قم بتثبيت آخر تحديث لـ Jester Mods Launcher، ثم أعد المحاولة."),
    )
}
